#pragma once
#include "native_hc_fixture.hpp"
#include "native_qsa_select_layout.hpp"
#include <algorithm>
namespace native_qsa_ss {
using namespace native_hc_fixture;
using namespace strata::core::portable_detail;
constexpr uint32_t canary=0x4acaf00d;
struct Fixture{uint32_t cells=4096,compute=1;std::array<int32_t,4>step{{16,17,4,17}};std::vector<float>pooled,dead,query;std::vector<uint32_t>seed;};
inline void validate(const Fixture&f){native_qsa_select_geometry(f.cells,f.step);native_hc_need(f.compute<=1&&f.pooled.size()==qsa_select_blocks(f.cells)*128&&f.dead.size()==128&&f.query.size()==512&&f.seed.size()==qsa_select_blocks(f.cells),"QSA score/select exact fixture spans");if(f.compute){for(size_t i=0;i<size_t(f.step[2])*128;++i)native_hc_normal(f.pooled[i]);for(auto*v:{&f.dead,&f.query})for(float x:*v)native_hc_normal(x);}}
inline uint32_t order_key(uint32_t b){uint32_t a=b&0x7fffffffu;if(a>0x7f800000u)return 0;if(a==0)b=0;return b&0x80000000u?~b:b|0x80000000u;}
inline std::vector<uint32_t> score_control(const Fixture&f){validate(f);auto out=f.seed;if(!f.compute)return out;for(int b=0;b<=f.step[2];++b){const float*k=b==f.step[2]?f.dead.data():f.pooled.data()+b*128;float score=0;for(size_t h=0;h<4;++h){std::array<float,32>d{};for(size_t lane=0;lane<32;++lane){size_t i=lane*4;float x=native_hc_normal(k[i]*f.query[h*128+i]);for(size_t j=1;j<4;++j)x=native_hc_normal(std::fma(k[i+j],f.query[h*128+i+j],x));d[lane]=x;}for(size_t o:{16,8,4,2,1}){auto old=d;for(size_t lane=0;lane<32;++lane)d[lane]=native_hc_normal(old[lane]+old[lane^o]);}score=native_hc_normal(score+(d[0]>0?d[0]:0.f));}if(b==f.step[2]&&f.step[1]%4)score=native_hc_normal(score+1e9f);out[b]=bits(score);}return out;}
// Independent policy oracle: sort CELL keys, then return selected cells ascending.
// Runtime implementations are the original native weighted radix algorithm.
inline std::vector<uint32_t> select_control(const Fixture&f,const std::vector<uint32_t>&scores){validate(f);native_hc_need(scores.size()==f.seed.size(),"QSA score span");std::vector<uint32_t>cells(size_t(f.step[1]));for(size_t i=0;i<cells.size();++i)cells[i]=uint32_t(i);if(f.step[1]>f.step[3]){std::sort(cells.begin(),cells.end(),[&](uint32_t a,uint32_t b){auto x=order_key(scores[a/4]),y=order_key(scores[b/4]);return x!=y?x>y:a<b;});cells.resize(f.step[3]);std::sort(cells.begin(),cells.end());}cells.resize(qsa_select_cap,canary);return cells;}
inline Fixture synthetic(unsigned mode){native_hc_need(mode<8,"QSA score/select case");Fixture f;const int n[]={17,256,4096,2052,2053,4096,2051,2053};int nk=n[mode];f.step={{nk-1,nk,nk/4,std::min(nk,int(qsa_select_cap))}};f.pooled.assign(qsa_select_blocks(f.cells)*128,0);f.dead.assign(128,0);f.query.assign(512,0);f.seed.assign(qsa_select_blocks(f.cells),canary);
 if(mode==1||mode==2){for(size_t i=0;i<f.pooled.size();++i)f.pooled[i]=float(int((i*19)%37)-18)/16.f;for(size_t i=0;i<128;++i)f.dead[i]=float(int(i%11)-5)/8.f;for(size_t i=0;i<512;++i)f.query[i]=float(int((i*7)%23)-11)/16.f;}
 if(mode==2){for(size_t i=0;i<512;++i)f.query[i]=0;const float v[]={0x1p24f,1.f,-0x1p24f,1.f};for(size_t i=0;i<4;++i)f.query[i]=v[i];}
 if(mode>=5){f.compute=0;const uint32_t special[]={0x7fc12345,0xffc12345,0x7f800000,0xff800000,0x80000000,0,0xbf800000,0x3f800000};for(size_t i=0;i<f.seed.size();++i)f.seed[i]=special[i%8];}
 if(mode==7){std::fill(f.seed.begin(),f.seed.end(),bits(2e9f));f.seed[f.step[2]]=bits(1e9f);}
 validate(f);return f;}
inline void write(const std::string&p,const Fixture&f){validate(f);native_hc_need(!std::filesystem::exists(p),"QSA fresh fixture");std::ofstream o(p,std::ios::binary);for(uint32_t w:{0x3153514eu,1u,f.cells,f.compute,qsa_select_cap,uint32_t(f.step[0]),uint32_t(f.step[1]),uint32_t(f.step[2]),uint32_t(f.step[3])})word(o,w);for(auto*v:{&f.pooled,&f.dead,&f.query})for(float x:*v)word(o,bits(x));for(auto x:f.seed)word(o,x);native_hc_need(bool(o),"QSA fixture write");}
inline Fixture read(const std::string&p){std::ifstream i(p,std::ios::binary);native_hc_need(bool(i)&&word(i)==0x3153514e&&word(i)==1,"QSA score/select header");Fixture f;f.cells=word(i);f.compute=word(i);native_hc_need(word(i)==qsa_select_cap,"QSA native selection cap");for(auto&v:f.step)v=int32_t(word(i));native_qsa_select_geometry(f.cells,f.step);native_hc_need(f.compute<=1,"QSA compute mode");f.pooled.resize(qsa_select_blocks(f.cells)*128);f.dead.resize(128);f.query.resize(512);f.seed.resize(qsa_select_blocks(f.cells));for(auto*v:{&f.pooled,&f.dead,&f.query})for(float&x:*v)x=value(word(i));for(auto&x:f.seed)x=word(i);native_hc_need(i.peek()==EOF,"QSA fixture trailing bytes");validate(f);return f;}
inline void contract(const Fixture&f,const std::string&p){native_hc_need(!std::filesystem::exists(p),"QSA fresh output contract");std::ofstream o(p);o<<"{\"fields\":{\"scores.f32le\":"<<f.seed.size()*4<<",\"selected.i32le\":"<<qsa_select_cap*4<<"},\"qualified\":false}\n";native_hc_need(bool(o),"QSA contract write");}
inline std::vector<uint32_t> words(const std::filesystem::path&p,size_t n){std::ifstream i(p,std::ios::binary);native_hc_need(bool(i),"QSA result missing");std::vector<uint32_t>v(n);for(auto&w:v)w=word(i);native_hc_need(i.peek()==EOF,"QSA result span");return v;}
inline void put(const std::filesystem::path&p,const std::vector<uint32_t>&v){std::ofstream o(p,std::ios::binary);for(auto x:v)word(o,x);native_hc_need(bool(o),"QSA result write");}
inline void check(const Fixture&f,const std::filesystem::path&d){auto score=words(d/"scores.f32le",f.seed.size());native_hc_need(score==score_control(f),"QSA exact native dot/FMA/XOR/ReLU/head/tail or inactive score differs");native_hc_need(words(d/"selected.i32le",qsa_select_cap)==select_control(f,score),"QSA weighted threshold/tie/ascending IDs or inactive cells differ");}
}
